def verify_n(n):
    """
    Implements the recursive backtracking algorithm to check if a pairing 
    exists for a given n.
    """
    if n <= 0:
        return False

    # Necessary condition check (optimization)
    # n(3n+1) must be divisible by 4
    if (n * (3 * n + 1)) % 4 != 0:
        return False

    N = 2 * n

    # Initialize available numbers and differences
    available_numbers = set(range(1, N + 1))
    differences = set(range(1, n + 1))

    # Sort differences to potentially improve search efficiency 
    # (though iterating over a set is fine, a list might be cleaner for ordered iteration)
    sorted_differences = sorted(list(differences))

    def solve(current_available, current_differences):
        # Base Case: All numbers and differences have been paired
        if not current_available:
            return True

        # Selection: Pick the smallest number k from AvailableNumbers
        k = min(current_available)

        # The remaining numbers are those in current_available excluding k
        remaining_available = current_available - {k}

        # Iteration: Try pairing k with all available differences d
        for d in current_differences:
            j = k + d

            # Check Constraints: j must be within bounds (<= 2n) and available
            if j <= N and j in remaining_available:

                # Form the new state
                new_available = remaining_available - {j}
                new_differences = current_differences - {d}

                # Recurse
                if solve(new_available, new_differences):
                    return True

        # Exhaustion: No successful pairing found starting from k
        return False

    return solve(available_numbers, differences)

